sections.render30Detail:
function render30Detail(p,r){
  const normal=(r.result||[]).map(n=>`<span class="mini-ball">${String(n).padStart(2,'0')}</span>`).join('');
  const special=p==='power655'&&r.special?`<span class="mini-ball special">${String(r.special).padStart(2,'0')}</span>`:'';
  const count=Number(r.reduced_total||r.final_portfolio_size||0),cap=p==='mega645'?220000:650000;
  if(count<=0||count>cap)return '<div class="draw30-body" style="color:#b42318;font-weight:900">KHÔNG THỐNG KÊ: số bộ dàn cuối vượt giới hạn hoặc chưa xác minh.</div>';
  const wins=r.reduced_wins||[];
  return `<div class="draw30-body"><div class="draw30-result">Kết quả: ${normal}${special?'<span style="margin:0 3px">|</span>'+special:''}</div>
    <div class="draw30-meta"><div>DÀN CUỐI ĐÃ CHẤM<b>${count.toLocaleString('vi-VN')} bộ</b></div><div>TỐI ĐA CHO PHÉP<b>${cap.toLocaleString('vi-VN')} bộ</b></div></div>
    <div><b>Chỉ dàn cuối:</b> ${compactPrizeChips(p,r.reduced_prize_counts||{})}</div>
    <div class="muted" style="color:#b42318;font-weight:700">Hồi kiểm tham chiếu theo điểm, chưa kiểm chứng đầy đủ với thuật toán dàn khách.</div>
    ${wins.length?'<div class="win-list">'+wins.map(w=>`<div class="win-ticket ${prizeClass(w.prize)}"><strong>${w.prize}</strong><code>${comboText(w.numbers)}</code></div>`).join('')+'</div>':'<div class="muted">Không có bộ trúng.</div>'}</div>`;
}

sections.renderStatsBox:
function renderStatsBox(p,box,elId,label,reducedBox=null){
  if(!box){$(elId).innerHTML='<div class="stats60-foot">Đang chờ kết quả hồi kiểm '+label+' trên máy chủ…</div>';return}
  const one=(b,title)=>{
    const c=b?.prize_counts||{},total=Number(b?.total_winning_tickets||0),rate=b?.draws_tested?((Number(b.winning_draws||0)/Number(b.draws_tested))*100).toFixed(1):'0.0';
    const jp=p==='power655'?`<div class="stat60-row jp"><span>Jackpot 1</span><b>${pcount(c,'Jackpot 1').toLocaleString('vi-VN')}</b></div><div class="stat60-row jp"><span>Jackpot 2</span><b>${pcount(c,'Jackpot 2').toLocaleString('vi-VN')}</b></div>`:`<div class="stat60-row jp"><span>Jackpot</span><b>${pcount(c,'Jackpot').toLocaleString('vi-VN')}</b></div>`;
    return `<div class="stats60-foot"><b>${title}</b></div><div class="stat60-row"><span>Số kỳ đã thống kê</span><b>${Number(b?.draws_tested||0).toLocaleString('vi-VN')}</b></div><div class="stat60-row"><span>Số kỳ có trúng thưởng</span><b>${Number(b?.winning_draws||0).toLocaleString('vi-VN')}</b></div><div class="stat60-row em"><span>Tổng số bộ trúng giải</span><b>${total.toLocaleString('vi-VN')}</b></div>${jp}<div class="stat60-row first"><span>Giải Nhất</span><b>${pcount(c,'Giải nhất').toLocaleString('vi-VN')}</b></div><div class="stat60-row second"><span>Giải Nhì</span><b>${pcount(c,'Giải nhì').toLocaleString('vi-VN')}</b></div><div class="stat60-row third"><span>Giải Ba</span><b>${pcount(c,'Giải ba').toLocaleString('vi-VN')}</b></div><div class="stat60-row em"><span>Tỷ lệ kỳ có giải</span><b>${rate}%</b></div><div class="stats60-foot">Cửa sổ ${fmt(b?.window_start)} → ${fmt(b?.window_end)} • trung bình ${Number(Math.round(b?.avg_pool??b?.avg_filtered_pool??0)).toLocaleString('vi-VN')} bộ/kỳ.</div>`;
  };
  const finalBox=reducedBox||box,limit=p==='mega645'?220000:650000;
  if(Number(finalBox?.avg_pool||0)>limit){$(elId).innerHTML='<div class="stats60-foot" style="color:#b42318">KHÔNG THỐNG KÊ: dàn vượt trần '+limit.toLocaleString('vi-VN')+' bộ.</div>';return}
  $(elId).innerHTML=one(finalBox,'CHỈ DÀN CUỐI — tối đa '+limit.toLocaleString('vi-VN')+' bộ (HỒI KIỂM THAM CHIẾU)');
}

sections.renderBacktestSummary:
function renderBacktestSummary(p,b){
 if(!b){$('statsBacktest').innerHTML='<div class="stats60-foot">Chưa có dữ liệu hồi kiểm.</div>';return}
 const format=n=>Number(n||0).toLocaleString('vi-VN'),cap=p==='mega645'?220000:650000;
 const rows=[30,60,150,1500].map(n=>{
  const x=b['reduced_stats'+n],total=Number(x?.avg_pool||0);
  if(!x||total<=0||total>cap)return '<div class="stats60-foot">'+format(n)+' kỳ: KHÔNG THỐNG KÊ nếu dàn cuối không hợp lệ hoặc vượt '+format(cap)+' bộ.</div>';
  const c=x.prize_counts||{},covered=Number(x.available_draws??x.draws_tested??0),state=x.complete?'đủ dữ liệu':'thiếu '+format(n-covered)+' kỳ';
  return '<div class="stat60-row em"><span>'+format(n)+' kỳ</span><b>'+format(covered)+'/'+format(n)+' — '+state+'</b></div>'+
   '<div class="stat60-row jp"><span>Jackpot dàn cuối</span><b>'+format(jackpotTickets(p,c))+'</b></div>'+
   '<div class="stat60-row first"><span>G1 dàn cuối</span><b>'+format(pcount(c,'Giải nhất'))+'</b></div>';
 });
 $('statsBacktest').innerHTML='<div class="stats60-foot" style="color:#b42318;font-weight:900">THAM CHIẾU: chưa đồng nhất với thuật toán dàn khách. Không cộng giải từ dàn sau lọc hàng triệu bộ.</div>'+rows.join('');
}

sections.renderAnalytics:
function renderAnalytics(p){
  const b=BT60?.products?.[p];
  const currentBacktest=BT60?.schema_version==='R17_USER32_ALL_METHODS_SAME_DAY_30DRAWS_60DRAWS_365D'
    &&Array.isArray(b?.method_names)&&b.method_names.length>0
    &&b?.filter_scope?.reduction_applied===true
    &&!!b?.reduced_stats60;
  if(!currentBacktest){
    $('detail30Heading').textContent='Chấm 30 kỳ gần nhất — đang tính lại';
    $('dailyReport').textContent='Đang tính lại bằng TOÀN BỘ điều kiện và TOÀN BỘ PP người dùng mới nhất. Không dùng số thống kê cũ.';
    $('reportHistory').innerHTML='<div class="muted" style="padding:10px;font-weight:850;color:#b42318">Thống kê cũ đã bị khóa hiển thị. Chờ backtest mới hoàn tất để tránh nhầm với kết quả trước khi thêm PP.</div>';
    $('stats60Heading').textContent='Thống kê 60 ngày — đang tính lại';
    $('stats60Range').textContent='Chỉ hiển thị hồi kiểm dàn cuối có đủ dữ liệu.';
    $('stats').innerHTML='<div class="stats60-foot" style="color:#b42318;font-weight:900">ĐANG TÍNH LẠI TOÀN BỘ PP NGƯỜI DÙNG • không hiển thị số R6 cũ.</div>';
    $('statsYear').innerHTML='<div class="stats60-foot" style="color:#b42318;font-weight:900">ĐANG TÍNH LẠI 1 NĂM bằng toàn bộ PP người dùng.</div>';
    $('statsBacktest').innerHTML='<div class="stats60-foot" style="color:#b42318;font-weight:900">ĐANG HỒI KIỂM 50 KỲ / 150 KỲ / TOÀN LỊCH SỬ bằng toàn bộ PP người dùng.</div>';
    return
  }
  const raw=(b.details30?.length?b.details30:b.details||[]).slice(-30),rows=raw.slice().reverse();
  const start=b.detail30_start||rows.at(-1)?.date,end=b.detail30_end||rows[0]?.date,span=calendarDays(start,end);
  $('detail30Heading').textContent=`Chấm ${rows.length} kỳ gần nhất${span?` (${span} ngày lịch)`:''}`;
  $('dailyReport').textContent=`HỒI KIỂM THAM CHIẾU ${rows.length}/30 kỳ • ${fmt(start)} → ${fmt(end)} • chỉ dàn cuối ≤${p==='mega645'?'220.000':'650.000'} bộ. Chưa đồng nhất bộ chọn dàn khách.`;
  $('reportHistory').innerHTML=rows.map(r=>`<details class="draw30-item"><summary><div class="draw30-top"><span class="draw-id">#${r.draw_id||'-'}</span><span class="draw-date">${fmt(r.date)}</span></div><div class="prize-chips">${compactPrizeChips(p,r.prize_counts||{})}</div><span class="detail-link">Chi tiết ›</span></summary>${render30Detail(p,r)}</details>`).join('')||'<div class="muted" style="padding:10px">Chưa có kỳ nào để chấm.</div>';
  const s60=b.stats60||null;
  if(s60){
    $('stats60Heading').textContent=`Thống kê 60 kỳ quay gần nhất (${Number(s60.draws_tested||0)} kỳ)`;
    const outsideJp=raw.filter(r=>r.date<s60.window_start||r.date>s60.window_end).reduce((a,r)=>a+jackpotTickets(p,r.prize_counts||{}),0);
    $('stats60Range').textContent=`Cửa sổ 60 kỳ quay: ${fmt(s60.window_start)} → ${fmt(s60.window_end)}.`+(outsideJp?` Trong 30 kỳ bên trái có ${outsideJp} Jackpot nằm ngoài cửa sổ 60 ngày nên không cộng vào thống kê 60 ngày.`:'');
  }else{$('stats60Heading').textContent='Thống kê 60 kỳ quay gần nhất';$('stats60Range').textContent='Đang tính cửa sổ 60 ngày…'}
  renderStatsBox(p,s60,'stats','60 kỳ',b.reduced_stats60||null);renderStatsBox(p,b.stats365||null,'statsYear','1 năm',b.reduced_stats365||null);renderBacktestSummary(p,b);
}
